async function checkRegistration(callback=registrationCallback){
 registrationCallback=callback;
 const pending={state:'pending'};registrationResult=pending;root.innerHTML=registrationPage();
 const result=await registrationOutcome(db.auth,callback);
 if(registrationResult!==pending)return;
 if(result.user)user=result.user;
 if(result.state==='success'&&callback.setup){registrationResult=null;registrationCallback={};authMode='setup';authMessage='';history.replaceState(null,'',location.pathname+'#/auth');lastHash=location.hash;await render();return;}
 registrationResult=result;
 history.replaceState(null,'',location.pathname+(new URLSearchParams(location.search).get('from')==='site'?'?from=site':'')+'#/registration-result');lastHash=location.hash;
 await render();window.scrollTo(0,0);document.querySelector('#verification-title')?.focus({preventScroll:true});
}
