async function fetchAll(table,columns='*'){let out=[],start=0;for(;;){const r=await db.from(table).select(columns).range(start,start+499);const rows=checkResult(r)||[];out.push(...rows);if(rows.length<500)break;start+=500;}return out;}
async function refresh(){if(demo||!user)return;const userId=user.id;const result=await Promise.all([fetchAll('cases'),fetchAll('observations'),fetchAll('photos'),staff?fetchAll('teacher_reviews'):Promise.resolve([]),role==='admin'?fetchAdminMembers():staff?fetchAll('profiles','id,display_name,class_name,email,created_at'):Promise.resolve([])]);if(user?.id!==userId)return;[cases,obs,photos,reviews,members]=result;archivedCases=cases.filter(c=>c.deleted_at);cases=cases.filter(c=>!c.deleted_at);cases.sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));loaded=true;}
function canManageRecord(c){return Boolean(c&&(demo||c.owner_id===user?.id||role==='admin'));}
function recordListTools(collection=false){return '<div class="section-head records-toolbar"><div><h2>'+(collection?'档案目录':'我的档案')+'</h2>'+(collection?'<small class="muted" id="collect-count"></small>':'')+'</div><a class="btn tiny secondary" href="#/trash">回收站'+(archivedCases.length?'（'+archivedCases.length+'）':'')+'</a></div><p class="small muted record-delete-hint">误填或测试档案可直接删除，误删可到回收站恢复。</p>';}
function recordRow(c){const items=obs.filter(o=>o.case_id===c.id),next=nextFollow(c,items);return '<article class="record-card"><a class="record" href="#/case/'+esc(c.id)+'"><div class="record-avatar">'+esc(c.name.slice(0,1))+'</div><div class="grow"><h3>'+esc(c.name)+' <span class="badge outline">'+(c.kind==='self'?'本人':'服务对象')+'</span></h3><p>'+esc(c.code)+' · '+esc(c.class_name||'未填班级')+'</p><div class="record-steps">'+STAGES.map(n=>'<i class="'+(items.some(o=>o.stage==='d'+n&&o.status==='submitted')?'done':'')+'"></i>').join('')+'</div></div><div class="record-meta">'+(next?'<span class="badge '+(next.date<=today()?'gold':'outline')+'">'+(next.date<=today()?'待跟进':'下次')+' '+dateText(next.date.slice(5))+'</span>':'<span class="badge">本阶段已记录</span>')+'<span>建档 '+dateText(c.created_on)+'</span></div><span class="arrow">›</span></a>'+(canManageRecord(c)?'<div class="record-actions"><small>建档人：'+esc(c.partner_name||'未填写')+'</small><button type="button" class="btn tiny danger-outline" data-delete-case="'+esc(c.id)+'" aria-label="删除档案：'+esc(c.name)+'">删除档案</button></div>':'')+'</article>';}
function dashboard(due=false){if(isTeacher()&&!due)return shell(managementHome({summary:summarize({cases,observations:obs,photos,reviews,members,userId:user?.id}),cases,profile,role},recordRow,icon));const dueCases=cases.filter(c=>{const n=nextFollow(c,obs);return n&&n.date<=today();});const days=cases.reduce((n,c)=>n+obs.filter(o=>o.case_id===c.id&&o.status==='submitted').length,0);return shell('<div class="page-heading"><div><div class="eyebrow">健康观察记录</div><h1>'+(due?'今天，继续跟进':isTeacher()?'档案总览':'我的空间')+'</h1><p>'+(due?'按已约定日期或阶段计划整理。':'为自己，也为每一位服务对象。')+'</p></div><a href="#/new" class="btn">'+icon('plus')+'为新会员建档</a></div><div class="stats"><div class="stat"><span>正在记录的档案</span><strong>'+cases.length+'</strong><small>份</small></div><div class="stat"><span>待跟进</span><strong>'+dueCases.length+'</strong><small>份</small></div><div class="stat"><span>已提交观察</span><strong>'+days+'</strong><small>次</small></div></div><a class="comparison-entry" href="#/comparisons"><div><span>照片 · 评分 · 连续跟进</span><strong>21天观察对照</strong><p>每份档案自动整理，随时回看每一次变化。</p></div><b>查看对照 ↗</b></a>'+recordListTools()+'<div class="filters"><input class="input" id="search" type="search" placeholder="搜索称呼、档案编号、班级" aria-label="搜索档案"><select id="kind-filter" aria-label="档案类型"><option value="">全部类型</option><option value="client">服务对象</option><option value="self">本人记录</option></select></div><div id="record-list" class="record-list" data-due="'+due+'">'+(due?dueCases:cases).map(recordRow).join('')+(!cases.length?'<div class="empty"><h3>开始第一份记录</h3><p>先建档，再按时间补充观察与照片。</p><a class="btn" href="#/new">新建档案</a></div>':'')+'</div>'+(!dueCases.length&&due?'<p class="empty">暂时没有到期的跟进记录。</p>':''),due?'due':'home');}
function newForm(c=null){const b=c?.baseline||{};return '<a class="back" href="#'+(c?'/case/'+c.id:'/home')+'">← 返回档案</a><div class="page-heading"><div><h1>'+(c?'编辑基本信息':'建立一份新档案')+'</h1><p>先填称呼并确认同意，其他资料可以稍后补充。</p></div></div><form id="case-form" class="panel" data-id="'+esc(c?.id||'')+'"><div id="form-error"></div><div id="matching-case-hint" class="notice matching-case" hidden></div><div class="grid2 record-required">'+select('为谁记录','kind',c?.kind||'client',[['client','为他人记录'],['self','为自己记录']])+field('姓名 / 称呼 <span class="gold">*</span>','name',c?.name||'','text','required maxlength="40" placeholder="可使用化名"')+'</div><details class="record-more"'+(c?' open':'')+'><summary>补充基本资料 <span class="small muted">选填 · 可稍后补充</span></summary><div class="grid2">'+field('建档日期','created_on',c?.created_on||today(),'date','required')+field('班级 / 期次','class_name',c?.class_name||profile.class_name||'','text','maxlength="80" placeholder="例如：第五期 · 泉州"')+field('记录学员 / 服务伙伴','partner_name',c?.partner_name||profile.display_name||'','text','maxlength="60"')+field('联系方式（选填）','contact',c?.contact||'','text','maxlength="80" placeholder="按本人意愿填写"')+'</div></details><details'+(c?' open':'')+'><summary>服务需求与首次了解 <span class="small muted">选填</span></summary><div class="field"><span class="label">本次服务需求</span>'+checks('needs',b.needs,NEEDS)+'</div><div class="field"><span class="label">当下体感</span>'+checks('feelings',b.feelings,FEELINGS)+'</div>'+area('最希望记录或改善的方面','wish',b.wish)+area('目前具体怎样','detail',b.detail)+area('过敏情况','allergy',b.allergy)+area('在用药 / 产品','meds',b.meds)+area('本人补充','extra',b.extra)+'</details><div class="form-section"><h3>先征得本人同意，再记录</h3>'+checkbox('consent_record','已取得本人同意建立记录，并由负责学员及何华清老师查看。<span class="gold">*</span>',c?.consent_record,'用于本次观察与跟进；为他人建档时，请先当面说明。')+checkbox('consent_photo','同意拍摄与私密保存观察照片。',c?.consent_photo,'可选；不同意不影响文字记录。')+checkbox('consent_teaching','同意将去除个人标识的记录用于教学案例。',c?.consent_teaching,'独立选择，默认不同意；之后可以在档案中撤回。')+'</div><p class="small muted">用于学习与状态观察，不作为诊断或疗效证明。</p><button class="btn full" type="submit">'+(c?'保存基本信息':'保存并进入首次观察')+'</button></form>';}
async function saveCase(form){const f=new FormData(form),id=form.dataset.id,c=cases.find(x=>x.id===id);if(!f.has('consent_record'))throw Error('请先征得本人同意，并勾选建档授权。');const payload={kind:f.get('kind'),name:String(f.get('name')).trim(),created_on:f.get('created_on'),class_name:f.get('class_name'),partner_name:f.get('partner_name'),contact:f.get('contact'),consent_record:true,consent_photo:f.has('consent_photo'),consent_teaching:f.has('consent_teaching'),baseline:{needs:f.getAll('needs'),feelings:f.getAll('feelings'),wish:f.get('wish'),detail:f.get('detail'),allergy:f.get('allergy'),meds:f.get('meds'),extra:f.get('extra')}};if(!payload.name)throw Error('请填写姓名或称呼。');if(demo){if(c)Object.assign(c,payload,{version:c.version+1});else{payload.id='demo-'+crypto.randomUUID();payload.code='A'+Math.random().toString(36).slice(2,9).toUpperCase();payload.owner_id='demo';payload.version=1;cases.unshift(payload);}}else if(c){checkResult(await db.from('cases').update({...payload,version:c.version+1}).eq('id',id).eq('version',c.version).select().single());}else{Object.assign(payload,checkResult(await db.from('cases').insert(payload).select().single()));}dirty=false;await refresh();notify(demo?'体验档案已保留在当前页面':'档案已保存到云端');activeStage='d1';go('/case/'+(id||payload.id));}
function ratingControls(r={}){return '<div class="ratings">'+ITEMS.map(([k,l])=>'<div class="rating-row"><span>'+l+'</span><div class="rating-buttons" role="group" aria-label="'+l+'评分">'+[1,2,3,4,5,0].map(n=>'<button type="button" data-rating="'+k+'" data-value="'+n+'" class="'+((r[k]||0)===n?'selected':'')+'" aria-pressed="'+((r[k]||0)===n)+'">'+(n||'未评')+'</button>').join('')+'<input type="hidden" name="rating_'+k+'" value="'+(r[k]||0)+'"></div></div>').join('')+'</div>';}
function productsHTML(rows=[],scope='actual'){
 const prefix=scope==='plan'?'plan_product_':'product_',plan=scope==='plan';
 return '<div id="'+(plan?'plan-product-rows':'product-rows')+'">'+rows.map((p,i)=>'<details class="product-row" data-index="'+i+'" data-product-scope="'+scope+'"><summary>'+esc(p.name)+' <span class="small muted">'+esc(p.useStatus||(p.unused?(plan?'不安排':'未使用'):(plan?'待填写':'待核对')))+(plan&&p.time?' · '+esc(p.time):'')+'</span></summary><div class="row between"><span class="small muted">'+(plan?'计划安排':'实际执行')+'</span><button type="button" class="text-btn" data-remove-product="'+i+'" data-scope="'+scope+'">移除此项</button></div><input type="hidden" name="'+prefix+'index" value="'+i+'"><input type="hidden" name="'+prefix+'name_'+i+'" value="'+esc(p.name)+'">'+select(plan?'计划状态':'使用状态',prefix+'status_'+i,p.useStatus||(p.unused?(plan?'不安排':'未使用'):(plan?'待填写':'待核对')),plan?['待填写','拟用','不安排']:['待核对','已使用','未使用','已填写'])+'<div class="record-select-grid">'+field(plan?'计划服用时间':'实际服用时间',prefix+'time_'+i,p.time||'','text','maxlength="80" placeholder="按本人情况填写"')+field('每次量',prefix+'amount_'+i,p.amount||'','text','maxlength="30"')+field('单位',prefix+'unit_'+i,p.unit||'','text','maxlength="20" placeholder="例如：袋、粒"')+field('每日次数',prefix+'times_'+i,p.perDay||'','text','maxlength="20"')+'</div>'+area('补充说明',prefix+'note_'+i,p.note,'按实际安排填写。')+'</details>').join('')+'</div>';
}
