function stageForm(c,stage){
 const original=obs.find(x=>x.case_id===c.id&&x.stage===stage);let o=original;
 const earlier=obs.filter(x=>x.case_id===c.id&&x.status==='submitted'&&Number(x.stage.slice(1))<Number(stage.slice(1))).sort((a,b)=>Number(b.stage.slice(1))-Number(a.stage.slice(1)))[0];
 if(!o?.data?.actions&&earlier?.data?.actions){o={...o,data:{...o?.data,actions:Object.fromEntries(FOUR_ACTIONS.map(([k])=>[k,{...earlier.data.actions[k],status:'未核对',feedback:''}]))}};}
 draftProducts=o?.data?.products||[];
 draftPlanProducts=(o?.data?.plan?.products||PRODUCTS.slice(0,6).map(name=>({name,useStatus:'待填写'}))).map(p=>productWithPlanTime(p));
 o={...o,data:{...o?.data,plan:{...o?.data?.plan,products:draftPlanProducts}}};
 const isOwner=demo||c.owner_id===user?.id;
 return renderStageForm(c,original?o:{...o,id:null},stage,{profile,demo,isOwner,uploadHTML:renderUploadFeedback(photoBatches.get(photoBatchKey(c,stage)),{demo}),photosHTML:photos.filter(p=>p.case_id===c.id&&p.stage===stage).map(photoThumb).join('')},{field,area,select,checkbox,ratingControls,productsHTML,icon});
}
