function comparisonsPage(){return shell('<div class="page-heading"><div><div class="eyebrow">OBSERVE · COMPARE · FOLLOW UP</div><h1>21天观察对照</h1><p>每份档案的照片、评分与跟进，集中在这里。</p></div><a class="btn secondary" href="#/home">返回档案</a></div><label class="comparison-search">查找档案<input type="search" class="input" id="comparison-search" placeholder="姓名、编号、班级或记录人"></label><div class="comparison-card-grid">'+comparisonCards(cases,obs,photos,photoURL)+'</div><div id="comparison-empty" class="empty" '+(cases.length?'hidden':'')+'><h3>'+(cases.length?'没有匹配的档案':'先建立一份档案')+'</h3><p>'+(cases.length?'试试姓名或档案编号。':'每次保存观察后，照片与评分自动形成对照。')+'</p>'+(!cases.length?'<a class="btn" href="#/new">为新会员建档</a>':'')+'</div>','comparisons');}
