function detailsPage(c,tab='record'){const items=obs.filter(o=>o.case_id===c.id),owned=demo||c.owner_id===user?.id;return shell('<a class="back" href="#'+(isTeacher()?'/collect':'/home')+'">← 返回档案列表</a><div class="page-heading"><div><div class="kicker">'+esc(c.code)+' · '+esc(c.class_name||'观察档案')+'</div><h1>'+esc(c.name)+' <span class="badge outline">'+(c.kind==='self'?'本人记录':'服务对象')+'</span></h1><p>建档 '+dateText(c.created_on)+' · 记录人 '+esc(c.partner_name||'未填写')+'</p></div><div class="case-heading-actions"><span class="badge gold">'+items.filter(x=>x.status==='submitted').length+' 次观察</span>'+((owned||role==='admin')?'<button class="btn tiny danger-outline case-delete" data-action="archive-case">删除档案</button>':'')+'</div></div><div class="tabs">'+[['record','观察记录'],['compare','21天对照'],['info','基本信息'],...(isTeacher()?[['review','老师整理']]:[])].map(([k,l])=>'<button data-tab="'+k+'" class="'+(k===tab?'active':'')+'">'+l+'</button>').join('')+'</div>'+(tab==='record'?'<div class="stage-rail">'+STAGES.map(n=>'<button class="stage-button '+(activeStage==='d'+n?'active ':'')+(items.some(o=>o.stage==='d'+n&&o.status==='submitted')?'done':'')+'" data-stage="d'+n+'"><strong>'+(n===1?'首次':'第'+n+'天')+'</strong><small>'+dateText(addDays(c.created_on,n-1).slice(5))+'</small></button>').join('')+'</div>'+stageForm(c,activeStage):tab==='compare'?comparison(c):tab==='review'?reviewForm(c):'<div class="panel"><h2>档案与授权</h2><dl><dt class="small muted">建档类型</dt><dd>'+esc(c.kind==='self'?'本人记录':'服务对象')+'</dd><dt class="small muted">联系方式</dt><dd>'+esc(c.contact||'未填写')+'</dd><dt class="small muted">拍照保存</dt><dd>'+(c.consent_photo?'已同意':'未同意')+'</dd><dt class="small muted">匿名教学案例</dt><dd>'+(c.consent_teaching?'已同意，可撤回':'未同意')+'</dd></dl><div class="divider"></div><h3>首次需求</h3><p class="small">'+esc((c.baseline?.needs||[]).join('、')||'未填写')+'</p><p class="small">'+esc(c.baseline?.wish||'未填写')+'</p><dl class="baseline-details">'+[['当下体感',(c.baseline?.feelings||[]).join('、')],['目前具体怎样',c.baseline?.detail],['过敏情况',c.baseline?.allergy],['在用药 / 产品',c.baseline?.meds],['本人补充',c.baseline?.extra]].map(([label,value])=>'<dt>'+label+'</dt><dd>'+esc(value||'未填写')+'</dd>').join('')+'</dl><p class="small muted">学生只可查看自己负责的档案，老师可查看本人已同意采集的记录。</p>'+(owned?'<div class="stack mt"><a class="btn secondary" href="#/edit/'+esc(c.id)+'">编辑信息与授权</a>'+(c.consent_teaching?'<button class="text-btn" data-action="revoke">撤回教学案例授权</button>':'')+'<button class="btn tiny danger-outline case-delete" data-action="archive-case">删除档案</button></div>':'')+'</div>'),'home');}
function reviewForm(c){const r=reviews.find(x=>x.case_id===c.id)||{};return '<form id="review-form" class="panel"><div id="form-error"></div><h2>保留原记录，单独做整理</h2><p class="small muted">老师评语不会改写学生的观察原文。</p>'+select('整理状态','org_status',r.org_status||'pending',[['pending','待整理'],['organized','已整理']])+field('主题标签（以逗号分隔）','tags',(r.tags||[]).join('，'),'text','maxlength="200" placeholder="例如：作息记录、连续观察"')+area('老师评语','comment',r.comment)+'<button class="btn" type="submit">保存整理</button><div class="divider"></div>'+(canTeach(c)?'<h3>已获独立教学授权</h3><p class="small muted">导出的案例默认只含匿名编号、日期与五项评分，不含姓名、电话、原始自由文本或照片。</p><button class="btn secondary" type="button" data-action="case-export">生成匿名案例页</button>':'<div class="well"><p>本人尚未同意教学案例使用。本档案不会纳入教学案例库。</p></div>')+'</form>';}
