async function moveCaseToTrash(c,archived){
 if(!canManageRecord(c))throw Error('您没有这份档案的删除或恢复权限。');
 const previousRoute=cleanHash(),listRoute=['/home','/due','/records','/collect','/library'].includes(previousRoute.split('?')[0]);
 const filters=[...document.querySelectorAll('#search,#kind-filter,#collect-search,#class-filter,#student-filter,#consent-filter,#stage-filter,#date-start,#date-end')].map(el=>[el.id,el.value]),scrollPosition=window.scrollY;
 document.querySelector('#dialog').close();
 busy=true;
 try{if(demo){const saved={...c,deleted_at:archived?new Date().toISOString():null,version:c.version+1};cases=cases.filter(x=>x.id!==c.id);archivedCases=archivedCases.filter(x=>x.id!==c.id);(archived?archivedCases:cases).unshift(saved);}else{checkResult(await db.rpc('set_case_archived',{p_case_id:c.id,p_archived:archived,p_expected_version:c.version}));await refresh();}dirty=false;currentCase=null;history.replaceState(null,'',archived?'#'+(listRoute?previousRoute:(isTeacher()?'/records':'/home')):'#/case/'+c.id);await render();if(archived&&listRoute){for(const [id,value] of filters){const el=document.getElementById(id);if(el){if(el.tagName==='SELECT'&&value&&![...el.options].some(o=>o.value===value))el.add(new Option(value,value));el.value=value;}}if(document.querySelector('#collect-list'))filterCollection();else if(document.querySelector('#record-list'))filterDashboard();window.scrollTo({top:scrollPosition,behavior:'instant'});}notify(archived?'已删除“'+c.name+'”，可在回收站恢复':'档案已恢复');}finally{busy=false;}
}
async function render(){const token=++loadId;let path=cleanHash();lastHash=location.hash;if(path==='/privacy'){root.innerHTML=privacy();return;}if(path==='/registration-result'){if(!registrationResult&&db){await checkRegistration();return;}root.innerHTML=registrationPage();return;}if(path==='/forgot'){registrationResult=null;registrationCallback={};authMode='forgot';root.innerHTML=authPage();return;}if(path==='/login'){root.innerHTML=authPage();return;}if(profileError&&!demo){root.innerHTML=connectionPage();return;}if(path==='/auth'&&user&&!demo&&authMode!=='setup'){path=requestedRoute;history.replaceState(null,'','#'+path);lastHash=location.hash;}if(path==='/auth'){root.innerHTML=authPage();return;}if(path==='/'&&!demo&&!user){root.innerHTML=welcome();return;}if(!demo&&!user){root.innerHTML=authPage();return;}if(!loaded){root.innerHTML='<div class="loading"><div class="mark">A</div><p>正在读取您的档案…</p></div>';try{await refresh();}catch(e){root.innerHTML=shell(errBox(friendly(e))+'<button class="btn mt" data-action="reload">重新读取</button>');return;}}if(token!==loadId)return;const parts=path.split('?')[0].split('/');if(parts[1]!=='case')currentCase=null;if(parts[1]==='case'){const c=cases.find(x=>x.id===parts[2]);if(!c){root.innerHTML=shell('<div class="empty">未找到档案，或当前账号无权查看。</div>');return;}if(currentCase?.id!==c.id)activeStage='d'+(nextFollow(c,obs)?.day||21);currentCase=c;const stageQuery=new URLSearchParams(path.split('?')[1]||'').get('stage');if(STAGES.some(n=>'d'+n===stageQuery))activeStage=stageQuery;const tab=parts[3]||'record';if(tab==='review'&&!isTeacher()){root.innerHTML=shell(errBox('没有老师权限。'));return;}try{await signPhotos(photos.filter(p=>p.case_id===c.id));}catch(e){notify('部分照片暂时未载入，请重试。');}if(token!==loadId)return;root.innerHTML=detailsPage(c,tab);}else if(parts[1]==='comparisons'){const previewPhotos=cases.flatMap(c=>{const v=comparisonAt(caseTimeline(c.id,obs,photos));return [v.baseline?.photos[0],v.selected?.photos[0]].filter(Boolean);});try{await signPhotos([...new Map(previewPhotos.map(p=>[p.id,p])).values()]);}catch(e){notify('部分照片暂时未载入，您仍可查看评分。');}if(token!==loadId)return;root.innerHTML=comparisonsPage();}else if(parts[1]==='new')root.innerHTML=shell(newForm(),'new');else if(parts[1]==='edit'){const c=cases.find(x=>x.id===parts[2]);root.innerHTML=shell(c&&(demo||c.owner_id===user?.id)?newForm(c):errBox('您没有编辑权限。'));}else if(['collect','records','library'].includes(parts[1])){root.innerHTML=collection(parts[1]==='library');if(isTeacher())filterCollection();}else if(parts[1]==='students'){root.innerHTML=studentsPage();if(isTeacher())filterMembers();}else if(parts[1]==='trash')root.innerHTML=trashPage();else if(parts[1]==='account')root.innerHTML=accountPage();else root.innerHTML=dashboard(parts[1]==='due');window.scrollTo({top:0,behavior:'instant'});}
async function saveObservation(form,intent,{quiet=false,formData=null,products=null}={}){
 const pending=uploadCounts(photoBatches.get(photoBatchKey())?.items||[]).pending;if(intent==='submitted'&&pending){document.querySelector('#upload-status')?.scrollIntoView({block:'center'});throw Error('还有'+pending+'张照片尚未上传成功，请先重试或移出待传列表，再保存并查看对照。');}
 const c=currentCase,f=formData||new FormData(form),existing=obs.find(o=>o.id===form.dataset.id),data={...existing?.data,ratings:Object.fromEntries(ITEMS.map(([k])=>[k,Number(f.get('rating_'+k))||null])),tongue:Object.fromEntries(['gloss','strength','source','coating','yinyang','form','axis'].map(k=>[k,f.get(k)])),compare:Object.fromEntries([0,1,2,3].map(k=>[k,f.get('compare_'+k)||'未评'])),products:activeStage==='d1'?(existing?.data?.products||[]):products||readProducts(form,'actual',f),...readWorkflow(f,activeStage,existing?.data)};
 if(data.tongue.source==='未观察')data.tongue.strength='待定';
 ['usage','action','usageNote','quote','handling','handlingReason','nextDate','nextMethod','lifeChange','tongueChange','partnerReview','nextService','nextFocus'].forEach(k=>{if(f.has(k))data[k]=f.get(k)||'';});
 const payload={case_id:c.id,stage:activeStage,actual_date:f.get('actual_date'),status:intent||'draft',data};let saved;
 if(demo)saved={...existing,...payload,id:existing?.id||crypto.randomUUID(),version:(existing?.version||0)+1};
 else if(existing)saved=checkResult(await db.from('observations').update({...payload,version:existing.version+1}).eq('id',existing.id).eq('version',existing.version).select().single());
 else saved=checkResult(await db.from('observations').insert(payload).select().single());
 obs=obs.filter(o=>o.id!==saved.id);obs.push(saved);form.dataset.id=saved.id;dirty=false;
 if(quiet){const status=form.querySelector('#save-state');if(status)status.textContent=demo?'体验记录已保存':'当前观察已保存到云端';return saved;}
 await refresh();notify(demo?'体验记录已保存至当前页面':intent==='draft'?'草稿已保存到云端':'已提交，照片与评分对照已更新');if(intent==='submitted')history.replaceState(null,'','#/case/'+c.id+'/compare?visit='+encodeURIComponent(saved.id));await render();return saved;
}
async function compress(file){cleanImageType(file);const url=URL.createObjectURL(file);try{const im=new Image();im.src=url;await im.decode();const factor=Math.min(1,1600/Math.max(im.width,im.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(im.width*factor));canvas.height=Math.max(1,Math.round(im.height*factor));const cx=canvas.getContext('2d');cx.fillStyle='#ffffff';cx.fillRect(0,0,canvas.width,canvas.height);cx.drawImage(im,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.88));if(!blob)throw Error('图片处理失败，请更换一张照片。');return blob;}finally{URL.revokeObjectURL(url);}}
