function download(content,type,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportCSV(){if(!isTeacher())throw Error('需要老师权限。');const records=filteredCollection(),rows=[['档案编号','称呼','类型','班级','记录学员','联系方式','建档日期','教学授权','观察阶段','实际日期','状态','精神','睡眠','食欲','排便','情绪','本人原话','下一回访日期','照片编号',...DETAIL_COLUMNS]];records.forEach(c=>{const list=obs.filter(o=>o.case_id===c.id);(list.length?list:[{}]).forEach(o=>rows.push([c.code,c.name,c.kind==='self'?'本人':'服务对象',c.class_name,c.partner_name,c.contact,c.created_on,c.consent_teaching?'同意':'不同意',o.stage?stageName(o.stage):'',o.actual_date,o.status==='submitted'?'已提交':'草稿',...ITEMS.map(([k])=>o.data?.ratings?.[k]??''),o.data?.quote||'',o.data?.nextDate||'',photos.filter(p=>p.case_id===c.id&&(!o.stage||p.stage===o.stage)).map(p=>p.file_no).join(' / '),...detailValues(c,o)]));});download(csv(rows),'text/csv;charset=utf-8','A表_'+(demo?'演示_':'')+'档案汇总_'+today()+'.csv');notify('已导出当前筛选的 '+records.length+' 份档案');}
async function exportCase(){if(!isTeacher())throw Error('需要老师权限。');let c=currentCase;if(!demo)c=checkResult(await db.from('cases').select('*').eq('id',c.id).single());if(!canTeach(c))throw Error('本档案尚未授权教学，或已撤回授权。');const list=obs.filter(o=>o.case_id===c.id&&o.status==='submitted').sort((a,b)=>a.actual_date.localeCompare(b.actual_date));const content='<h1>匿名观察案例 · '+esc(c.code)+'</h1><p>用于课程学习与状态观察，不作为诊断或疗效证明。</p><p>仅导出日期与本人主观评分，未包含姓名、电话、原始自由文本和照片。</p><table><thead><tr><th>日期</th><th>节点</th>'+ITEMS.map(([,l])=>'<th>'+l+'</th>').join('')+'</tr></thead><tbody>'+list.map(o=>'<tr><td>'+esc(o.actual_date)+'</td><td>'+stageName(o.stage)+'</td>'+ITEMS.map(([k])=>'<td>'+esc(o.data?.ratings?.[k]??'未评')+'</td>').join('')+'</tr>').join('')+'</tbody></table><p>1 差 · 2 偏差 · 3 一般 · 4 较好 · 5 很好；“未评”不计为分值。</p><p>生成日期：'+today()+(demo?' · 演示数据':'')+'</p>';dialog('<div class="case-print">'+content+'</div><div class="dialog-actions"><button class="btn secondary" data-action="close-dialog">返回</button><button class="btn" id="download-case">下载匿名案例</button></div>');document.querySelector('#download-case').onclick=()=>{download('<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><title>匿名观察案例 '+esc(c.code)+'</title><style>body{max-width:850px;margin:40px auto;padding:25px;font:16px/1.8 sans-serif;color:#173c33}table{width:100%;border-collapse:collapse}td,th{border:1px solid #ddd;padding:10px}h1{font-size:26px}@media print{body{margin:0}}</style>'+content+'</html>','text/html;charset=utf-8','匿名观察案例_'+c.code+'.html');document.querySelector('#dialog').close();};}
async function saveReview(form){if(!isTeacher())throw Error('没有老师权限。');const f=new FormData(form),payload={case_id:currentCase.id,org_status:f.get('org_status'),tags:String(f.get('tags')).split(/[,，]/).map(s=>s.trim()).filter(Boolean),comment:f.get('comment'),updated_at:new Date().toISOString()};if(demo){const old=reviews.find(r=>r.case_id===currentCase.id);if(old)Object.assign(old,payload);else reviews.push(payload);}else checkResult(await db.from('teacher_reviews').upsert({...payload,updated_by:user.id}));dirty=false;await refresh();notify('整理已保存');}
