document.addEventListener('click',async e=>{const b=e.target.closest('button,a');const a=e.target.closest('a[href^="#/"]');if(busy&&b){e.preventDefault();notify('正在保存或上传，请稍候。');return;}if(a){e.preventDefault();go(a.getAttribute('href').slice(1));return;}const z=e.target.closest('[data-zoom]');if(z){dialog('<img src="'+esc(z.dataset.zoom)+'" alt="观察照片放大查看"><div class="dialog-actions"><button class="btn secondary" data-action="close-dialog">关闭</button></div>',true);return;}if(!b)return;try{if(b.dataset.memberDelete){await openMemberDeletion(b.dataset.memberDelete);return;}if(b.dataset.removeUpload){const batch=photoBatches.get(photoBatchKey()),item=batch?.items.find(i=>i.id===b.dataset.removeUpload);if(item&&item.status!=='success'){URL.revokeObjectURL(item.preview);batch.items=batch.items.filter(i=>i!==item);batch.error='';if(!batch.items.length)photoBatches.delete(photoBatchKey());updatePhotoFeedback();}return;}if(b.dataset.deleteCase){confirmCaseTrash(cases.find(c=>c.id===b.dataset.deleteCase),true);return;}if(b.dataset.confirmTrash){await moveCaseToTrash([...cases,...archivedCases].find(c=>c.id===b.dataset.confirmTrash),b.dataset.archived==='true');return;}if(b.dataset.restoreCase){confirmCaseTrash(archivedCases.find(c=>c.id===b.dataset.restoreCase),false);return;}if(b.dataset.auth){authMode=['signup','forgot'].includes(b.dataset.auth)?b.dataset.auth:'login';authMessage='';go(cleanHash()==='/login'?'/login':'/auth');return;}if(b.dataset.rating){const group=b.closest('.rating-buttons');group.querySelectorAll('button').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});group.querySelector('input').value=b.dataset.value;dirty=true;updateObservationProgress();return;}if(b.dataset.tab){go('/case/'+currentCase.id+'/'+b.dataset.tab);return;}if(b.dataset.stage){if(dirty&&!confirm('当前观察尚未保存，确定切换吗？'))return;activeStage=b.dataset.stage;dirty=false;go('/case/'+currentCase.id+'?stage='+activeStage);return;}if(b.dataset.removeProduct!==undefined){const form=document.querySelector('#observation-form'),scope=b.dataset.scope||'actual',rows=readProducts(form,scope);rows.splice(Number(b.dataset.removeProduct),1);document.querySelector(scope==='plan'?'#plan-product-rows':'#product-rows').outerHTML=productsHTML(rows,scope);if(scope==='plan')draftPlanProducts=rows;else draftProducts=rows;dirty=true;updateObservationProgress();return;}if(b.dataset.deletePhoto){if(!confirm('确定删除这张照片？此操作无法撤销。'))return;const p=photos.find(x=>x.id===b.dataset.deletePhoto);if(demo){if(p.url?.startsWith('blob:'))URL.revokeObjectURL(p.url);photos=photos.filter(x=>x.id!==p.id);}else{checkResult(await db.storage.from('case-photos').remove([p.storage_path]));checkResult(await db.from('photos').delete().eq('id',p.id));await refresh();}render();return;}switch(b.dataset.action){case 'verification-continue':await continueRegistration(b.dataset.destination);break;case 'verification-login':returnToLogin();break;case 'verification-retry':if(db)await checkRegistration();else location.reload();break;case 'reconnect-account':await reconnectAccount();break;case 'copy-browser-link':await copyBrowserLink(b);break;case 'retry-photos':await performPhotoUpload();break;case 'archive-case':confirmCaseTrash(currentCase,true);break;case 'start':live()?go('/auth'):beginDemo(false);break;case 'student-demo':beginDemo(false);break;case 'exit-demo':if((dirty||hasPendingPhotos())&&!confirm('退出后，体验记录会丢失。确定退出吗？'))break;photos.forEach(p=>{if(p.url?.startsWith('blob:'))URL.revokeObjectURL(p.url);});clearPhotoBatches();demo=false;teacherDemo=false;dirty=false;cases=[];archivedCases=[];obs=[];photos=[];loaded=false;go('/');break;case 'logout':if(hasPendingPhotos()&&!confirm('还有未成功上传的照片，退出后需重新选择。确定退出吗？'))break;checkResult(await db.auth.signOut({scope:'local'}));user=null;loaded=false;cases=[];archivedCases=[];obs=[];photos=[];signed.clear();go('/');break;case 'reload':case 'refresh-workspace':if(!demo&&user)await loadProfile();loaded=false;render();break;case 'pick-photo':case 'take-photo':choosingPhoto=true;document.querySelector(b.dataset.action==='pick-photo'?'#photo-input':'#camera-input').click();break;case 'add-product':case 'add-product-template':{const form=document.querySelector('#observation-form'),scope=b.dataset.scope||'actual',rows=readProducts(form,scope);let names=PRODUCTS.slice(0,6);if(b.dataset.action==='add-product'){let name=document.querySelector(scope==='plan'?'#plan-product-select':'#product-select').value;if(name==='other'){dialog('<h2>添加其他产品</h2><label class="label" for="custom-product-name">产品名称</label><input class="input" id="custom-product-name" maxlength="80"><div class="dialog-actions"><button class="btn secondary" data-action="close-dialog">取消</button><button class="btn" data-action="confirm-product" data-scope="'+scope+'">添加</button></div>');break;}names=[name];}for(const name of names){if(!rows.some(p=>p.name===name))rows.push(productWithPlanTime({name,time:'',amount:'',unit:'',perDay:'',unused:false,useStatus:scope==='plan'?'待填写':'待核对'},scope));}document.querySelector(scope==='plan'?'#plan-product-rows':'#product-rows').outerHTML=productsHTML(rows,scope);dirty=true;updateObservationProgress();break;}case 'confirm-product':{const name=document.querySelector('#custom-product-name').value.trim(),scope=b.dataset.scope||'actual';if(!name){notify('请填写产品名称');break;}const rows=readProducts(document.querySelector('#observation-form'),scope);rows.push(productWithPlanTime({name,useStatus:scope==='plan'?'待填写':'待核对'},scope));document.querySelector(scope==='plan'?'#plan-product-rows':'#product-rows').outerHTML=productsHTML(rows,scope);document.querySelector('#dialog').close();dirty=true;updateObservationProgress();break;}case 'csv-export':exportCSV();break;case 'case-export':await exportCase();break;case 'close-dialog':memberDeletion=null;document.querySelector('#dialog').close();break;case 'revoke':if(confirm('撤回后，本档案将从教学案例库排除。确定撤回吗？')){await patchCase({consent_teaching:false});notify('已撤回教学案例授权');}break;case 'request-delete':if(confirm('提交删除申请后，老师可在后台看到申请。原记录在完成删除前仍会保留。')){await patchCase({deletion_requested:true});notify('删除申请已记录');}break;}}catch(err){notify(friendly(err));}});
