async function loadProfile(){
  const userId=user?.id;if(!userId)return;
  try{
    const p=checkResult(await db.from('profiles').select('*').eq('id',userId).maybeSingle());
    const rows=checkResult(await db.from('user_roles').select('role').eq('user_id',userId))||[];
    if(user?.id!==userId)return;
    profile=p||{};role=accountRole(rows);staff=role==='teacher'||role==='admin';profileError='';
  }catch(e){
    if(user?.id!==userId)return;
    profile={};staff=false;role='student';members=[];loaded=false;cases=[];archivedCases=[];obs=[];photos=[];reviews=[];currentCase=null;signed.clear();profileError='account_unavailable';
    throw e;
  }
}
async function reconnectAccount(){
  if(!db){location.reload();return;}
  try{
    const session=checkResult(await db.auth.getSession()).session;
    if(!session){clearSession();go('/auth');return;}
    if(user?.id!==session.user.id)clearSession();
    user=session.user;await loadProfile();loaded=false;
    if(authMode!=='setup'&&cleanHash()==='/auth')history.replaceState(null,'','#'+requestedRoute);
    await render();
  }catch(e){profileError='account_unavailable';await render();notify('连接还未恢复，请稍后重试。');}
}
function clearSession(){clearPhotoBatches();profileError='';loadId++;user=null;profile={};staff=false;role='student';members=[];loaded=false;cases=[];archivedCases=[];obs=[];photos=[];reviews=[];currentCase=null;signed.clear();}
async function boot(){
  const callback=authCallback(location.hash,location.search);
  registrationCallback=callback;
  const verificationEntry=callback.signup||callback.setup||Boolean(callback.error)||cleanHash()==='/registration-result';
  if(verificationEntry){registrationResult={state:'pending'};root.innerHTML=registrationPage();}
  if(live()){
    try{
      if(!window.supabase||!config.url||!config.key)throw Error('账号连接暂时不可用，请刷新后重试。');
      db=window.supabase.createClient(config.url,config.key,{
        global:{fetch:publicApiFetch(config.key)},
        auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}
      });
      db.auth.onAuthStateChange((event,session)=>{
        if(event==='SIGNED_OUT'){
          registrationResult=null;registrationCallback={};authMode='login';clearSession();
          if(!demo){dirty=false;history.replaceState(null,'','#/auth');setTimeout(()=>render(),0);}return;
        }
        if(authMode==='signup'&&busy&&event==='SIGNED_IN'){if(session?.user)user=session.user;return;}
        if(registrationResult){if(registrationResult.state==='success'&&event==='SIGNED_IN'&&session?.user.id!==registrationResult.user.id){registrationResult=null;registrationCallback={};clearSession();history.replaceState(null,'','#/auth');}else{if(session?.user)user=session.user;return;}}
        if(event==='TOKEN_REFRESHED'&&session&&user?.id===session.user.id)user=session.user;
        else if(event==='SIGNED_IN'&&session)setTimeout(async()=>{if(user?.id===session.user.id)return;clearSession();user=session.user;try{await loadProfile();}catch{}if(cleanHash()==='/login')history.replaceState(null,'','#'+requestedRoute);await render();},0);
      });
      if(verificationEntry){await checkRegistration(callback);return;}
      const session=checkResult(await db.auth.getSession());
      user=session.session?.user||null;
      if(user){
        if(callback.setup){authMode='setup';history.replaceState(null,'','#/auth');}
        else if(callback.received)history.replaceState(null,'','#/home');
        await loadProfile();
      }else if(callback.setup||callback.error){
        authMessage=callback.error||'链接已失效，请重新获取开通或密码重设邮件。';
        history.replaceState(null,'','#/auth');
      }

    }catch(e){if(verificationEntry){registrationResult={state:'retry'};history.replaceState(null,'','#/registration-result');await render();return;}profileError='account_unavailable';notify('连接暂未完成，请稍后重试。');}
  }
  if(cleanHash()==='/tongue-demo'||cleanHash()==='/followup-demo'){const section=cleanHash();demo=true;teacherDemo=false;seedDemo();go(section==='/tongue-demo'?'/case/demo-1/compare':'/due');return;}
  if(cleanHash()==='/demo'){beginDemo(false);return;}
  if(cleanHash()==='/teacher-demo'){history.replaceState(null,'','#/auth');}
  await render();
}
window.addEventListener('online',()=>{if(profileError&&!busy)reconnectAccount();});
boot();

